19	import java.util.Arrays;
20	
21	/**
22	 * <p>A simple, fast array of bits, represented compactly by an array of ints internally.</p>
23	 *
24	 * @author Sean Owen
25	 */
26	public final class BitArray implements Cloneable {
27	
28	  private static final int[] EMPTY_BITS = {};
29	  private static final float LOAD_FACTOR = 0.75f;
30	
31	  private int[] bits;
32	  private int size;
33	
34	  public BitArray() {
35	    this.size = 0;
36	    this.bits = EMPTY_BITS;
37	  }
38	
39	  public BitArray(int size) {
40	    this.size = size;
41	    this.bits = makeArray(size);
42	  }
43	
44	  // For testing only
45	  BitArray(int[] bits, int size) {
46	    this.bits = bits;
47	    this.size = size;
48	  }
49	
50	  public int getSize() {
51	    return size;
52	  }
53	
54	  public int getSizeInBytes() {
55	    return (size + 7) / 8;
56	  }
57	
58	  private void ensureCapacity(int newSize) {
59	    if (newSize > bits.length * 32) {
60	      int[] newBits = makeArray((int) Math.ceil(newSize / LOAD_FACTOR));
61	      System.arraycopy(bits, 0, newBits, 0, bits.length);
62	      this.bits = newBits;
63	    }
64	  }
65	
66	  /**
67	   * @param i bit to get
68	   * @return true iff bit i is set
69	   */
70	  public boolean get(int i) {
71	    return (bits[i / 32] & (1 << (i & 0x1F))) != 0;
72	  }
73	
74	  /**
75	   * Sets bit i.
76	   *
77	   * @param i bit to set
78	   */
79	  public void set(int i) {
80	    bits[i / 32] |= 1 << (i & 0x1F);
81	  }
82	
83	  /**
84	   * Flips bit i.
85	   *
86	   * @param i bit to set
87	   */
88	  public void flip(int i) {
89	    bits[i / 32] ^= 1 << (i & 0x1F);
90	  }
91	
92	  /**
93	   * @param from first bit to check
94	   * @return index of first bit that is set, starting from the given index, or size if none are set
95	   *  at or beyond this given index
96	   * @see #getNextUnset(int)
97	   */
98	  public int getNextSet(int from) {
99	    if (from >= size) {
100	      return size;
101	    }
102	    int bitsOffset = from / 32;
103	    int currentBits = bits[bitsOffset];
104	    // mask off lesser bits first
105	    currentBits &= -(1 << (from & 0x1F));
106	    while (currentBits == 0) {
107	      if (++bitsOffset == bits.length) {
108	        return size;
109	      }
110	      currentBits = bits[bitsOffset];
111	    }
112	    int result = (bitsOffset * 32) + Integer.numberOfTrailingZeros(currentBits);
113	    return Math.min(result, size);
114	  }
115	
116	  /**
117	   * @param from index to start looking for unset bit
118	   * @return index of next unset bit, or {@code size} if none are unset until the end
119	   * @see #getNextSet(int)
120	   */
121	  public int getNextUnset(int from) {
122	    if (from >= size) {
123	      return size;
124	    }
125	    int bitsOffset = from / 32;
126	    int currentBits = ~bits[bitsOffset];
127	    // mask off lesser bits first
128	    currentBits &= -(1 << (from & 0x1F));
129	    while (currentBits == 0) {
130	      if (++bitsOffset == bits.length) {
131	        return size;
132	      }
133	      currentBits = ~bits[bitsOffset];
134	    }
135	    int result = (bitsOffset * 32) + Integer.numberOfTrailingZeros(currentBits);
136	    return Math.min(result, size);
137	  }
138	
139	  /**
140	   * Sets a block of 32 bits, starting at bit i.
141	   *
142	   * @param i first bit to set
143	   * @param newBits the new value of the next 32 bits. Note again that the least-significant bit
144	   * corresponds to bit i, the next-least-significant to i+1, and so on.
145	   */
146	  public void setBulk(int i, int newBits) {
147	    bits[i / 32] = newBits;
148	  }
149	
150	  /**
151	   * Sets a range of bits.
152	   *
153	   * @param start start of range, inclusive.
154	   * @param end end of range, exclusive
155	   */
156	  public void setRange(int start, int end) {
157	    if (end < start || start < 0 || end > size) {
158	      throw new IllegalArgumentException();
159	    }
160	    if (end == start) {
161	      return;
162	    }
163	    end--; // will be easier to treat this as the last actually set bit -- inclusive
164	    int firstInt = start / 32;
165	    int lastInt = end / 32;
166	    for (int i = firstInt; i <= lastInt; i++) {
167	      int firstBit = i > firstInt ? 0 : start & 0x1F;
168	      int lastBit = i < lastInt ? 31 : end & 0x1F;
169	      // Ones from firstBit to lastBit, inclusive
170	      int mask = (2 << lastBit) - (1 << firstBit);
171	      bits[i] |= mask;
172	    }
173	  }
174	
175	  /**
176	   * Clears all bits (sets to false).
177	   */
178	  public void clear() {
179	    int max = bits.length;
180	    for (int i = 0; i < max; i++) {
181	      bits[i] = 0;
182	    }
183	  }
184	
185	  /**
186	   * Efficient method to check if a range of bits is set, or not set.
187	   *
188	   * @param start start of range, inclusive.
189	   * @param end end of range, exclusive
190	   * @param value if true, checks that bits in range are set, otherwise checks that they are not set
191	   * @return true iff all bits are set or not set in range, according to value argument
192	   * @throws IllegalArgumentException if end is less than start or the range is not contained in the array
193	   */
194	  public boolean isRange(int start, int end, boolean value) {
195	    if (end < start || start < 0 || end > size) {
196	      throw new IllegalArgumentException();
197	    }
198	    if (end == start) {
199	      return true; // empty range matches
200	    }
201	    end--; // will be easier to treat this as the last actually set bit -- inclusive
202	    int firstInt = start / 32;
203	    int lastInt = end / 32;
204	    for (int i = firstInt; i <= lastInt; i++) {
205	      int firstBit = i > firstInt ? 0 : start & 0x1F;
206	      int lastBit = i < lastInt ? 31 : end & 0x1F;
207	      // Ones from firstBit to lastBit, inclusive
208	      int mask = (2 << lastBit) - (1 << firstBit);
209	
210	      // Return false if we're looking for 1s and the masked bits[i] isn't all 1s (that is,
211	      // equals the mask, or we're looking for 0s and the masked portion is not all 0s
212	      if ((bits[i] & mask) != (value ? mask : 0)) {
213	        return false;
214	      }
215	    }
216	    return true;
217	  }
218	
219	  public void appendBit(boolean bit) {
220	    ensureCapacity(size + 1);
221	    if (bit) {
222	      bits[size / 32] |= 1 << (size & 0x1F);
223	    }
224	    size++;
225	  }
226	
227	  /**
228	   * Appends the least-significant bits, from value, in order from most-significant to
229	   * least-significant. For example, appending 6 bits from 0x000001E will append the bits
230	   * 0, 1, 1, 1, 1, 0 in that order.
231	   *
232	   * @param value {@code int} containing bits to append
233	   * @param numBits bits from value to append
234	   */
235	  public void appendBits(int value, int numBits) {
236	    if (numBits < 0 || numBits > 32) {
237	      throw new IllegalArgumentException("Num bits must be between 0 and 32");
238	    }
239	    int nextSize = size;
240	    ensureCapacity(nextSize + numBits);
241	    for (int numBitsLeft = numBits - 1; numBitsLeft >= 0; numBitsLeft--) {
242	      if ((value & (1 << numBitsLeft)) != 0) {
243	        bits[nextSize / 32] |= 1 << (nextSize & 0x1F);
244	      }
245	      nextSize++;
246	    }
247	    size = nextSize;
248	  }
249	
250	  public void appendBitArray(BitArray other) {
251	    int otherSize = other.size;
252	    ensureCapacity(size + otherSize);
253	    for (int i = 0; i < otherSize; i++) {
254	      appendBit(other.get(i));
255	    }
256	  }
257	
258	  public void xor(BitArray other) {
259	    if (size != other.size) {
260	      throw new IllegalArgumentException("Sizes don't match");
261	    }
262	    for (int i = 0; i < bits.length; i++) {
263	      // The last int could be incomplete (i.e. not have 32 bits in
264	      // it) but there is no problem since 0 XOR 0 == 0.
265	      bits[i] ^= other.bits[i];
266	    }
267	  }
268	
269	  /**
270	   *
271	   * @param bitOffset first bit to start writing
272	   * @param array array to write into. Bytes are written most-significant byte first. This is the opposite
273	   *  of the internal representation, which is exposed by {@link #getBitArray()}
274	   * @param offset position in array to start writing
275	   * @param numBytes how many bytes to write
276	   */
277	  public void toBytes(int bitOffset, byte[] array, int offset, int numBytes) {
278	    for (int i = 0; i < numBytes; i++) {
279	      int theByte = 0;
280	      for (int j = 0; j < 8; j++) {
281	        if (get(bitOffset)) {
282	          theByte |= 1 << (7 - j);
283	        }
284	        bitOffset++;
285	      }
286	      array[offset + i] = (byte) theByte;
287	    }
288	  }
289	
290	  /**
291	   * @return underlying array of ints. The first element holds the first 32 bits, and the least
292	   *         significant bit is bit 0.
293	   */
294	  public int[] getBitArray() {
295	    return bits;
296	  }
297	
298	  /**
299	   * Reverses all bits in the array.
300	   */
301	  public void reverse() {
302	    int[] newBits = new int[bits.length];
303	    // reverse all int's first
304	    int len = (size - 1) / 32;
305	    int oldBitsLen = len + 1;
306	    for (int i = 0; i < oldBitsLen; i++) {
307	      newBits[len - i] = Integer.reverse(bits[i]);
308	    }
309	    // now correct the int's if the bit size isn't a multiple of 32
310	    if (size != oldBitsLen * 32) {
311	      int leftOffset = oldBitsLen * 32 - size;
312	      int currentInt = newBits[0] >>> leftOffset;
313	      for (int i = 1; i < oldBitsLen; i++) {
314	        int nextInt = newBits[i];
315	        currentInt |= nextInt << (32 - leftOffset);
316	        newBits[i - 1] = currentInt;
317	        currentInt = nextInt >>> leftOffset;
318	      }
319	      newBits[oldBitsLen - 1] = currentInt;
320	    }
321	    bits = newBits;
322	  }
323	
324	  private static int[] makeArray(int size) {
325	    return new int[(size + 31) / 32];
326	  }
327	
328	  @Override
329	  public boolean equals(Object o) {
330	    if (!(o instanceof BitArray)) {
331	      return false;
332	    }
333	    BitArray other = (BitArray) o;
334	    return size == other.size && Arrays.equals(bits, other.bits);
335	  }
336	
337	  @Override
338	  public int hashCode() {
339	    return 31 * size + Arrays.hashCode(bits);
340	  }
341	
342	  @Override
343	  public String toString() {
344	    StringBuilder result = new StringBuilder(size + (size / 8) + 1);
345	    for (int i = 0; i < size; i++) {
346	      if ((i & 0x07) == 0) {
347	        result.append(' ');
348	      }
349	      result.append(get(i) ? 'X' : '.');
350	    }
351	    return result.toString();
352	  }
353	
354	  @Override
355	  public BitArray clone() {
356	    return new BitArray(bits.clone(), size);
357	  }
358	
359	}
