27	 * @author dswitkin@google.com (Daniel Switkin)
28	 */
29	public final class PlanarYUVLuminanceSource extends LuminanceSource {
30	
31	  private static final int THUMBNAIL_SCALE_FACTOR = 2;
32	
33	  private final byte[] yuvData;
34	  private final int dataWidth;
35	  private final int dataHeight;
36	  private final int left;
37	  private final int top;
38	
39	  public PlanarYUVLuminanceSource(byte[] yuvData,
40	                                  int dataWidth,
41	                                  int dataHeight,
42	                                  int left,
43	                                  int top,
44	                                  int width,
45	                                  int height,
46	                                  boolean reverseHorizontal) {
47	    super(width, height);
48	
49	    if (left < 0 || top < 0 || width < 0 || height < 0 ||
50	        width > dataWidth - left || height > dataHeight - top) {
51	      throw new IllegalArgumentException("Crop rectangle does not fit within image data.");
52	    }
53	
54	    this.yuvData = yuvData;
55	    this.dataWidth = dataWidth;
56	    this.dataHeight = dataHeight;
57	    this.left = left;
58	    this.top = top;
59	    if (reverseHorizontal) {
60	      reverseHorizontal(width, height);
61	    }
62	  }
63	
64	  @Override
65	  public byte[] getRow(int y, byte[] row) {
66	    if (y < 0 || y >= getHeight()) {
67	      throw new IllegalArgumentException("Requested row is outside the image: " + y);
68	    }
69	    int width = getWidth();
70	    if (row == null || row.length < width) {
71	      row = new byte[width];
72	    }
73	    int offset = (y + top) * dataWidth + left;
74	    System.arraycopy(yuvData, offset, row, 0, width);
75	    return row;
76	  }
77	
78	  @Override
79	  public byte[] getMatrix() {
80	    int width = getWidth();
81	    int height = getHeight();
82	
83	    // If the caller asks for the entire underlying image, save the copy and give them the
84	    // original data. The docs specifically warn that result.length must be ignored.
85	    if (width == dataWidth && height == dataHeight) {
86	      return yuvData;
87	    }
88	
89	    int area = width * height;
90	    byte[] matrix = new byte[area];
91	    int inputOffset = top * dataWidth + left;
92	
93	    // If the width matches the full width of the underlying data, perform a single copy.
94	    if (width == dataWidth) {
95	      System.arraycopy(yuvData, inputOffset, matrix, 0, area);
96	      return matrix;
97	    }
98	
99	    // Otherwise copy one cropped row at a time.
100	    for (int y = 0; y < height; y++) {
101	      int outputOffset = y * width;
102	      System.arraycopy(yuvData, inputOffset, matrix, outputOffset, width);
103	      inputOffset += dataWidth;
104	    }
105	    return matrix;
106	  }
107	
108	  @Override
109	  public boolean isCropSupported() {
110	    return true;
111	  }
112	
113	  @Override
114	  public LuminanceSource crop(int left, int top, int width, int height) {
115	    return new PlanarYUVLuminanceSource(yuvData,
116	                                        dataWidth,
117	                                        dataHeight,
118	                                        this.left + left,
119	                                        this.top + top,
120	                                        width,
121	                                        height,
122	                                        false);
123	  }
124	
125	  public int[] renderThumbnail() {
126	    int width = getWidth() / THUMBNAIL_SCALE_FACTOR;
127	    int height = getHeight() / THUMBNAIL_SCALE_FACTOR;
128	    int[] pixels = new int[width * height];
129	    byte[] yuv = yuvData;
130	    int inputOffset = top * dataWidth + left;
131	
132	    for (int y = 0; y < height; y++) {
133	      int outputOffset = y * width;
134	      for (int x = 0; x < width; x++) {
135	        int grey = yuv[inputOffset + x * THUMBNAIL_SCALE_FACTOR] & 0xff;
136	        pixels[outputOffset + x] = 0xFF000000 | (grey * 0x00010101);
137	      }
138	      inputOffset += dataWidth * THUMBNAIL_SCALE_FACTOR;
139	    }
140	    return pixels;
141	  }
142	
143	  /**
144	   * @return width of image from {@link #renderThumbnail()}
145	   */
146	  public int getThumbnailWidth() {
147	    return getWidth() / THUMBNAIL_SCALE_FACTOR;
148	  }
149	
150	  /**
151	   * @return height of image from {@link #renderThumbnail()}
152	   */
153	  public int getThumbnailHeight() {
154	    return getHeight() / THUMBNAIL_SCALE_FACTOR;
155	  }
156	
157	  private void reverseHorizontal(int width, int height) {
158	    byte[] yuvData = this.yuvData;
159	    for (int y = 0, rowStart = top * dataWidth + left; y < height; y++, rowStart += dataWidth) {
160	      int middle = rowStart + width / 2;
161	      for (int x1 = rowStart, x2 = rowStart + width - 1; x1 < middle; x1++, x2--) {
162	        byte temp = yuvData[x1];
163	        yuvData[x1] = yuvData[x2];
164	        yuvData[x2] = temp;
165	      }
166	    }
167	  }
168	
169	}
