17	package com.google.zxing.client.j2se;
18	
19	import com.google.zxing.BinaryBitmap;
20	import com.google.zxing.DecodeHintType;
21	import com.google.zxing.LuminanceSource;
22	import com.google.zxing.MultiFormatReader;
23	import com.google.zxing.NotFoundException;
24	import com.google.zxing.Result;
25	import com.google.zxing.ResultPoint;
26	import com.google.zxing.client.result.ParsedResult;
27	import com.google.zxing.client.result.ResultParser;
28	import com.google.zxing.common.BitArray;
29	import com.google.zxing.common.BitMatrix;
30	import com.google.zxing.common.HybridBinarizer;
31	import com.google.zxing.multi.GenericMultipleBarcodeReader;
32	import com.google.zxing.multi.MultipleBarcodeReader;
33	
34	import javax.imageio.ImageIO;
35	import java.awt.image.BufferedImage;
36	import java.io.IOException;
37	import java.io.StringWriter;
38	import java.net.URI;
39	import java.nio.charset.StandardCharsets;
40	import java.nio.file.Files;
41	import java.nio.file.Path;
42	import java.nio.file.Paths;
43	import java.util.ArrayList;
44	import java.util.Arrays;
45	import java.util.Collection;
46	import java.util.List;
47	import java.util.Map;
48	import java.util.Queue;
49	import java.util.concurrent.Callable;
50	
51	/**
52	 * One of a pool of threads which pulls images off the Inputs queue and decodes them in parallel.
53	 *
54	 * @see CommandLineRunner
55	 */
56	final class DecodeWorker implements Callable<Integer> {
57	
58	  private static final int RED = 0xFFFF0000;
59	  private static final int BLACK = 0xFF000000;
60	  private static final int WHITE = 0xFFFFFFFF;
61	
62	  private final DecoderConfig config;
63	  private final Queue<URI> inputs;
64	  private final Map<DecodeHintType,?> hints;
65	
66	  DecodeWorker(DecoderConfig config, Queue<URI> inputs) {
67	    this.config = config;
68	    this.inputs = inputs;
69	    hints = config.buildHints();
70	  }
71	
72	  @Override
73	  public Integer call() throws IOException {
74	    int successful = 0;
75	    for (URI input; (input = inputs.poll()) != null;) {
76	      Result[] results = decode(input, hints);
77	      if (results != null) {
78	        successful++;
79	        if (config.dumpResults) {
80	          dumpResult(input, results);
81	        }
82	      }
83	    }
84	    return successful;
85	  }
86	
87	  private static Path buildOutputPath(URI input, String suffix) throws IOException {
88	    Path outDir;
89	    String inputFileName;
90	    if ("file".equals(input.getScheme())) {
91	      Path inputPath = Paths.get(input);
92	      outDir = inputPath.getParent();
93	      inputFileName = inputPath.getFileName().toString();
94	    } else {
95	      outDir = Paths.get(".").toRealPath();
96	      String path = input.getPath();
97	      if (path == null) {
98	        inputFileName = "input";
99	      } else {
100	        String[] pathElements = path.split("/");
101	        inputFileName = pathElements[pathElements.length - 1];
102	      }
103	    }
104	
105	    // Replace/add extension
106	    int pos = inputFileName.lastIndexOf('.');
107	    if (pos > 0) {
108	      inputFileName = inputFileName.substring(0, pos) + suffix;
109	    } else {
110	      inputFileName += suffix;
111	    }
112	
113	    return outDir.resolve(inputFileName);
114	  }
115	
116	  private static void dumpResult(URI input, Result... results) throws IOException {
117	    Collection<String> resultTexts = new ArrayList<>();
118	    for (Result result : results) {
119	      resultTexts.add(result.getText());
120	    }
121	    Files.write(buildOutputPath(input, ".txt"), resultTexts, StandardCharsets.UTF_8);
122	  }
123	
124	  private Result[] decode(URI uri, Map<DecodeHintType,?> hints) throws IOException {
125	    BufferedImage image = ImageReader.readImage(uri);
126	
127	    LuminanceSource source;
128	    if (config.crop == null) {
129	      source = new BufferedImageLuminanceSource(image);
130	    } else {
131	      List<Integer> crop = config.crop;
132	      source = new BufferedImageLuminanceSource(
133	          image, crop.get(0), crop.get(1), crop.get(2), crop.get(3));
134	    }
135	
136	    BinaryBitmap bitmap = new BinaryBitmap(new HybridBinarizer(source));
137	    if (config.dumpBlackPoint) {
138	      dumpBlackPoint(uri, image, bitmap);
139	    }
140	
141	    MultiFormatReader multiFormatReader = new MultiFormatReader();
142	    Result[] results;
143	    try {
144	      if (config.multi) {
145	        MultipleBarcodeReader reader = new GenericMultipleBarcodeReader(multiFormatReader);
146	        results = reader.decodeMultiple(bitmap, hints);
147	      } else {
148	        results = new Result[]{multiFormatReader.decode(bitmap, hints)};
149	      }
150	    } catch (NotFoundException ignored) {
151	      System.out.println(uri + ": No barcode found");
152	      return null;
153	    }
154	
155	    if (config.brief) {
156	      System.out.println(uri + ": Success");
157	    } else {
158	      StringWriter output = new StringWriter();
159	      for (Result result : results) {
160	        ParsedResult parsedResult = ResultParser.parseResult(result);
161	        output.write(uri +
162	            " (format: " + result.getBarcodeFormat() +
163	            ", type: " + parsedResult.getType() + "):\n" +
164	            "Raw result:\n" +
165	            result.getText() + "\n" +
166	            "Parsed result:\n" +
167	            parsedResult.getDisplayResult() + "\n");
168	
169	        if (config.outputRaw) {
170	          StringBuilder rawData = new StringBuilder();
171	          byte[] rawBytes = result.getRawBytes();
172	
173	          if (rawBytes != null) {
174	            for (byte b : rawBytes) {
175	              rawData.append(String.format("%02X", b & 0xff));
176	              rawData.append(" ");
177	            }
178	            rawData.setLength(rawData.length() - 1);  // chop off final space
179	
180	            output.write("Raw bits:\n" + rawData + "\n");            
181	          }
182	        }
183	
184	        ResultPoint[] resultPoints = result.getResultPoints();
185	        int numResultPoints = resultPoints.length;
186	        output.write("Found " + numResultPoints + " result points.\n");
187	        for (int pointIndex = 0; pointIndex < numResultPoints; pointIndex++) {
188	          ResultPoint rp = resultPoints[pointIndex];
189	          if (rp != null) {
190	            output.write("  Point " + pointIndex + ": (" + rp.getX() + ',' + rp.getY() + ')');
191	            if (pointIndex != numResultPoints - 1) {
192	              output.write('\n');
193	            }
194	          }
195	        }
196	        output.write('\n');
197	      }
198	      System.out.println(output);
199	    }
200	
201	    return results;
202	  }
203	
204	  /**
205	   * Writes out a single PNG which is three times the width of the input image, containing from left
206	   * to right: the original image, the row sampling monochrome version, and the 2D sampling
207	   * monochrome version.
208	   */
209	  private static void dumpBlackPoint(URI uri, BufferedImage image, BinaryBitmap bitmap) throws IOException {
210	    int width = bitmap.getWidth();
211	    int height = bitmap.getHeight();
212	    int stride = width * 3;
213	    int[] pixels = new int[stride * height];
214	
215	    // The original image
216	    int[] argb = new int[width];
217	    for (int y = 0; y < height; y++) {
218	      image.getRGB(0, y, width, 1, argb, 0, width);
219	      System.arraycopy(argb, 0, pixels, y * stride, width);
220	    }
221	
222	    // Row sampling
223	    BitArray row = new BitArray(width);
224	    for (int y = 0; y < height; y++) {
225	      try {
226	        row = bitmap.getBlackRow(y, row);
227	      } catch (NotFoundException nfe) {
228	        // If fetching the row failed, draw a red line and keep going.
229	        int offset = y * stride + width;
230	        Arrays.fill(pixels, offset, offset + width, RED);
231	        continue;
232	      }
233	
234	      int offset = y * stride + width;
235	      for (int x = 0; x < width; x++) {
236	        pixels[offset + x] = row.get(x) ? BLACK : WHITE;
237	      }
238	    }
239	
240	    // 2D sampling
241	    try {
242	      for (int y = 0; y < height; y++) {
243	        BitMatrix matrix = bitmap.getBlackMatrix();
244	        int offset = y * stride + width * 2;
245	        for (int x = 0; x < width; x++) {
246	          pixels[offset + x] = matrix.get(x, y) ? BLACK : WHITE;
247	        }
248	      }
249	    } catch (NotFoundException ignored) {
250	      // continue
251	    }
252	
253	    writeResultImage(stride, height, pixels, uri, ".mono.png");
254	  }
255	
256	  private static void writeResultImage(int stride,
257	                                       int height,
258	                                       int[] pixels,
259	                                       URI input,
260	                                       String suffix) throws IOException {
261	    BufferedImage result = new BufferedImage(stride, height, BufferedImage.TYPE_INT_ARGB);
262	    result.setRGB(0, 0, stride, height, pixels, 0, stride);
263	    Path imagePath = buildOutputPath(input, suffix);
264	    try {
265	      if (!ImageIO.write(result, "png", imagePath.toFile())) {
266	        System.err.println("Could not encode an image to " + imagePath);
267	      }
268	    } catch (IOException ignored) {
269	      System.err.println("Could not write to " + imagePath);
270	    }
271	  }
272	
273	}
